import React from "react";
import { Theme, Link, Image, Box, LinkBox, Section, Hr, Text, Strong } from "@quarkly/widgets";
import { Override } from "@quarkly/components";

export default (() => {
  return(
    <Section
      sm-width="100% border-box"
      sm-height="6rem"
      padding="0 0 0 0"
      id="header">
      <Override
        slot="SectionContent"
        flex-direction="column"
        justify-content="center"
        sm-display="flex"
        sm-align-items="center"
        sm-justify-content="center"
        sm-flex-direction="row"
        sm-flex-wrap="no-wrap"
        sm-align-content="stretch"
        height="4rem"
        align-items="center"
        display="flex"
        flex-wrap="wrap"
        align-content="space-between"
        sm-height="100%"
        margin="0.5rem auto 0.5rem auto"
      />
      <LinkBox
        href="/"
        height="100%"
        display="flex"
        justify-content="space-between"
        align-items="center"
        flex-direction="row"
        sm-align-items="center"
        sm-flex-direction="row"
        sm-justify-content="center"
        md-width="60%"
        lg-width="70%"
        md-justify-content="center"
        sm-display="flex"
        sm-flex-wrap="no-wrap"
        flex-wrap="no-wrap"
        align-content="flex-start"
        sm-height="60%"
        sm-width="100%"
        width="30%"
      >
        <Image
          src="/assets/ims_banner.png"
          flex="0 1 auto"
          order="0"
          sm-width="100%"
          margin="0px 0px 0px 2rem"
          height="80%"
          sm-margin="0px 0px 0px 0px"
        />
      </LinkBox>

      <Box
        min-width="100px"
        min-height="100px"
        sm-display="flex"
        sm-justify-content="center"
        sm-flex-wrap="no-wrap"
        sm-flex-direction="row"
        sm-align-items="center"
        align-items="center"
        display="flex"
        flex-direction="row"
        justify-content="center"
        sm-width="100%"
        sm-height="20%"
        sm-min-width="auto"
        sm-min-height="auto"
        sm-padding="0 0px 0 0px"
        sm-margin="0px 0px 0.5rem 0px"
        flex-wrap="no-wrap"
      >
        <LinkBox href="https://imsresearch.substack.com" target="_blank" height="100%">
          <Image
            src="/assets/substack_icon.png"
            display="flex"
            sm-margin="0px 2rem 0px 2rem"
            margin="0px 1rem 0 1rem"
            sm-height="100%"
            width="40px"
            height="40px"
            sizes="(max-width: 576px) 100vw,(max-width: 768px) 100vw,(max-width: 992px) 100vw,100vw"
          />
        </LinkBox>
        <LinkBox href="https://discord.gg/2FfmwydAr3Hq" target="_blank" height="100%">
          <Image
            src="/assets/discord_icon.png"
            display="block"
            sm-align-self="flex-start"
            sm-margin="0px 2rem 0px 2rem"
            width="50px"
            height="50px"
            margin="0px 1rem 0px 1rem"
            sm-height="100%"
            sizes="(max-width: 576px) 100vw,(max-width: 768px) 100vw,(max-width: 992px) 100vw,100vw"
          />
        </LinkBox>
        <LinkBox href="https://www.youtube.com/playlist?list=PLJmTEYXxCKpnL_hVZCVMU4OP77dU5Q6IH" target="_blank" height="100%">
          <Image
            src="/assets/youtube_icon.png"
            display="flex"
            sm-margin="0px 2rem 0px 2rem"
            width="50px"
            height="50px"
            margin="0px 1rem 0px 1rem"
            sm-height="100%"
            
            sizes="(max-width: 576px) 100vw,(max-width: 768px) 100vw,(max-width: 992px) 100vw,100vw"
          />
        </LinkBox>
      </Box>
    </Section>
  );
});