import React from "react";
import { Theme, Link, Image, Box, LinkBox, Section, Hr, Text, Strong } from "@quarkly/widgets";
import { Override } from "@quarkly/components";

export default (() => {
  return(
    <Section
      padding="0.8rem 0 0.8rem 0.5rem"
      sm-padding="0 0 0 0"
      display="flex"
      width="100%"
      flex-wrap="wrap"
    >
      <Override
        slot="SectionContent"
        sm-display="flex"
        sm-flex-direction="row"
        sm-flex-wrap="wrap"
        sm-align-items="center"
        sm-justify-content="center"
        sm-align-content="stretch"
        sm-height="100% border-box"
        sm-width="100%"
        display="flex"
        flex-direction="row"
        flex-wrap="wrap"
        align-items="center"
        justify-content="flex-start"
        margin="0px auto 0px auto"
        padding="0px 0px 0px 1.5rem"
        sm-padding="0.5rem 0px 0.5rem 0"
      />
      <LinkBox
        href="/about-us"
        padding="0 1rem 0 0"
        sm-padding="0 1rem 0 1rem"
        sm-margin="0 0 0.5rem 0"
        align-items="center"
      >
        <Text
          font="1.3rem --fontFamily-sans"
          sm-font="0.8rem --fontFamily-sans"
          sm-text-align="center"
          margin="0px 0 0px 0"
        >
          About us
        </Text>
      </LinkBox>
      <LinkBox
          href="/systems-event"
          padding="0px 1rem 0px 1rem"
          sm-padding="0 1rem 0 1rem"
          sm-margin="0 0 0.5rem 0"
          border-style="dashed"
          border-width="0 0 0 0.2rem"
          sm-border-width="0 0 0 0.15rem"
          align-self="stretch"
          align-items="center"
        >
          <Text
            font="1.3rem --fontFamily-sans"
            sm-font="0.8rem --fontFamily-sans"
            sm-text-align="center"
            margin="0px 0 0px 0"
            padding="0 0.2rem 0 0.2rem"
            color="yellow"
            style={{background: "linear-gradient(to right, #ff0066 0%, #ff6600 100%)"}}>
            The Systems Event <br></br>
          </Text>
      </LinkBox>

      {/*journal navbox*/}
      <Box
        border-style="dashed"
        border-width="0.2rem"
        sm-border-width="0.15rem"
        display="flex"
        flex-direction="row"
      >
        <LinkBox
          href="/journal"
          sm-display="flex"
          sm-flex-direction="column"
          sm-flex-wrap="no-wrap"
          sm-overflow="visible"
          sm-align-items="center"
          sm-justify-content="center"
          padding="0px 1rem 0px 1rem"
          sm-padding="0.2rem 1rem 0.2rem 1rem"
        >
          <Text font="1.3rem --fontFamily-sans" sm-font="0.8rem --fontFamily-sans" sm-text-align="center" margin="0px 0 0px 0">
            Latest Issue <br></br>
          </Text>
        </LinkBox>
        <LinkBox
          href="/publish-with-us"
          display="flex"
          flex-direction="row"
          flex-wrap="no-wrap"
          padding="0px 1rem 0px 1rem"
          border-width="0 0 0 0.2rem"
          sm-border-style="none"
          sm-padding="0.2rem 1rem 0.2rem 1rem"
        >
          <Text margin="0px 0.2rem 0px 0" font="1.3rem --fontFamily-sans" sm-font="0.8rem --fontFamily-sans" sm-text-align="center">
            Publish with us
          </Text>
        </LinkBox>
        <LinkBox
          href="/publish-with-us/style-guide"
          display="flex"
          flex-direction="row"
          flex-wrap="no-wrap"
          padding="0px 0.5rem 0px 1rem"
          border-width="0 0 0 0.2rem"
          sm-border-style="none"
          sm-padding="0.2rem 1rem 0.2rem 1rem"
        >
          <Text margin="0px 0.2rem 0px 0" font="1.3rem --fontFamily-sans" sm-font="0.8rem --fontFamily-sans" sm-text-align="center">
            Style guide
          </Text>
        </LinkBox>
      </Box>

      <Box md-width="100%" sm-height="0.1rem"/>
      {/*second section*/}

      <LinkBox
        href="https://imsresearch.substack.com/s/news"
        target="_blank"
        display="flex"
        flex-direction="row"
        flex-wrap="no-wrap"
        padding="0px 1rem 0px 1rem"
        margin="0 0 0 1rem"
        sm-align-items="center"
        sm-display="flex"
        sm-flex-direction="row"
        sm-justify-content="space-between"
        sm-flex-wrap="no-wrap"
        border-width="0 0 0 0.2rem"
        border-style="solid"
        border-color="rgba(200,200,200,0.6)"
        sm-border-style="none"
        sm-padding="0.2rem 1rem 0 1rem"
      >
        <Text margin="0px 0.2rem 0px 0" font="1.3rem --fontFamily-sans" sm-font="0.8rem --fontFamily-sans">
          News
        </Text>
        <Image
          src="/assets/external_icon.png"
          display="block"
          width="5px"
          sizes="(max-width: 576px) 100vw,(max-width: 768px) 100vw,(max-width: 992px) 100vw,100vw"
        />
      </LinkBox>
      <LinkBox
        href="https://imsresearch.substack.com/s/articlesessays"
        target="_blank"
        display="flex"
        flex-direction="row"
        flex-wrap="no-wrap"
        padding="0px 1rem 0px 1rem"
        sm-align-items="center"
        sm-display="flex"
        sm-flex-direction="row"
        sm-justify-content="space-between"
        sm-flex-wrap="no-wrap"
        sm-padding="0.2rem 1rem 0 1rem"
      >
        <Text margin="0px 0.2rem 0px 0" font="1.3rem --fontFamily-sans" sm-font="0.8rem --fontFamily-sans" sm-text-align="center">
          Articles/Essays
        </Text>
        <Image
          src="/assets/external_icon.png"
          display="block"
          width="5px"
          sizes="(max-width: 576px) 100vw,(max-width: 768px) 100vw,(max-width: 992px) 100vw,100vw"
        >
        </Image>
      </LinkBox>
      <LinkBox
        href="https://imsresearch.substack.com/s/opinion"
        target="_blank"
        display="flex"
        flex-direction="row"
        flex-wrap="no-wrap"
        padding="0px 1rem 0px 1rem"
        sm-padding="0.2rem 1rem 0 1rem"
      >
        <Text margin="0px 0.2rem 0px 0" font="1.3rem --fontFamily-sans" sm-font="0.8rem --fontFamily-sans">
          Opinion
        </Text>
        <Image
          src="/assets/external_icon.png"
          display="block"
          width="5px"
          sizes="(max-width: 576px) 100vw,(max-width: 768px) 100vw,(max-width: 992px) 100vw,100vw"
        />
      </LinkBox>

      <Box width="100%" sm-height="0.1rem"/>
      {/*sitemap link*/}
      <LinkBox
        href="/sitemap"
        display="flex"
        flex-direction="row"
        flex-wrap="no-wrap"
        padding="0px 1rem 0px 0"
        sm-align-items="center"
        sm-display="flex"
        sm-flex-direction="row"
        sm-justify-content="space-between"
        sm-flex-wrap="no-wrap"
        sm-border-style="none"
      >
        <Text margin="0px 0.2rem 0px 0" font="1rem --fontFamily-sans" sm-font="0.5rem --fontFamily-sans">
          Sitemap
        </Text>
      </LinkBox>

    </Section>
  );
});