import React from "react";
import { Theme, Link, Image, Box, LinkBox, Section, Text, Strong } from "@quarkly/widgets";

export default (() => {
  return(
    <Section
      padding="3rem 0 2rem 0"
      quarkly-title="Footer-10"
      md-padding="4rem 0 2rem 0"
      sm-padding="4rem 0 2rem 0"
      lg-padding="4rem 0 2rem 0"
    >
      <Box
        display="flex"
        lg-width="100%"
        flex-direction="row"
        lg-flex-direction="row"
        justify-content="space-between"
        width="100%"
        padding="0 0px 0 0px"
        md-padding="0 0px 30px 0px"
        lg-padding="0 0px 50px 0px"
        sm-flex-direction="column"
        md-flex-direction="column"
        md-display="flex"
        md-grid-gap="52px"
      >
        <Box
          lg-margin="0px 0px 0px 0px"
          width="30%"
          display="flex"
          lg-width="50%"
          sm-width="100%"
          flex-direction="column"
          padding="0px 50px 0px 0px"
          sm-margin="0px 0px 0px 0px"
        >
          <Text
            font="normal 1rem/1.2 --fontFamily-sans"
          >
            <a href="#header">(Top)</a>
          </Text>
          <LinkBox
            justify-content="center"
            border-radius="100%"
            width="80px"
            height="80px"
            align-items="center"
            display="flex"
            href="/#header"
          >
            <Image
              src="/assets/main_logo.png"
              display="block"
              width="80px"
              height="80px"
              overflow="visible"
              sizes="(max-width: 576px) 100vw,(max-width: 768px) 100vw,(max-width: 992px) 100vw,100vw"
            />
          </LinkBox>
          <Text
            margin="1rem 0px 1rem 0px"
            font="normal 200 1rem/1.2 --fontFamily-sans"
            color="#5a5d64"
            sm-text-align="left"
            sm-margin="1rem 0px 1rem 0px"
          >
            <Strong
              overflow-wrap="normal"
              word-break="normal"
              white-space="normal"
              text-indent="0"
              text-overflow="clip"
              hyphens="manual"
              user-select="auto"
              pointer-events="auto"
            >
              ©
            </Strong>
            {" "}2026 Institute of Minecraft Studies
          </Text>
          <Text
            margin="0rem 0px 1rem 0px"
            font="normal 200 0.8rem/1.5 --fontFamily-sans"
            color="#5a5d64"
            sm-text-align="left"
            sm-margin="0 0px 1rem 0px"
          >
            <Strong
              overflow-wrap="normal"
              word-break="normal"
              white-space="normal"
              text-indent="0"
              text-overflow="clip"
              hyphens="manual"
              user-select="auto"
              pointer-events="auto"
            >
              Website built by @matcha_tea
            </Strong>
          </Text>
          <Box
            min-width="10px"
            min-height="10px"
            display="grid"
            grid-template-columns="repeat(5, 1fr)"
            grid-gap="16px 24px"
            md-align-self="flex-start"
            align-self="flex-start"
          >
            <LinkBox href="https://imsresearch.substack.com" width="30px" height="30px">
              <Image
                src="/assets/substack_icon.png"
                display="block"
                width="20px"
                height="20px"
                margin="0px 1rem 0px 1rem"
                sizes="(max-width: 576px) 100vw,(max-width: 768px) 100vw,(max-width: 992px) 100vw,100vw"
              />
            </LinkBox>
            <LinkBox href="https://discord.gg/2FfmwydAr3Hq" width="30px" height="30px">
              <Image
                src="/assets/discord_icon.png"
                display="block"
                width="30px"
                height="30px"
                margin="0px 1rem 0px 1rem"
                sizes="(max-width: 576px) 100vw,(max-width: 768px) 100vw,(max-width: 992px) 100vw,100vw"
              />
            </LinkBox>
            <LinkBox href="https://www.youtube.com/playlist?list=PLJmTEYXxCKpnL_hVZCVMU4OP77dU5Q6IH" width="30px" height="30px">
              <Image
                src="/assets/youtube_icon.png"
                display="block"
                width="30px"
                height="30px"
                margin="0px 1rem 0px 1rem"
                sizes="(max-width: 576px) 100vw,(max-width: 768px) 100vw,(max-width: 992px) 100vw,100vw"
              />
            </LinkBox>
          </Box>
        </Box>
      </Box>
    </Section>
  );
});